targets.expr:
max by (litellm_model_name) (
  litellm_deployment_state{job=~"$job", instance=~"$instance", litellm_model_name=~"$model", api_base!=""}
  and on (litellm_model_name)
  (
    (
      label_replace(max by (model) (increase(litellm_requests_metric_total{job=~"$job", instance=~"$instance"}[$__range])), "litellm_model_name", "$1", "model", "(.*)")
      or
      label_replace(max by (requested_model) (increase(litellm_proxy_failed_requests_metric_total{job=~"$job", instance=~"$instance"}[$__range])), "litellm_model_name", "$1", "requested_model", "(.*)")
    ) > 0
  )
)

histogram_quantile(
  0.50,
  sum by (model, le) (
    rate(litellm_llm_api_latency_metric_bucket{job=~"$job", instance=~"$instance", model=~"$model"}[$__rate_interval])
  )
)

histogram_quantile(
  0.90,
  sum by (model, le) (
    rate(litellm_llm_api_latency_metric_bucket{job=~"$job", instance=~"$instance", model=~"$model"}[$__rate_interval])
  )
)

histogram_quantile(
  0.95,
  sum by (model, le) (
    rate(litellm_llm_api_latency_metric_bucket{job=~"$job", instance=~"$instance", model=~"$model"}[$__rate_interval])
  )
)

histogram_quantile(
  0.99,
  sum by (model, le) (
    rate(litellm_llm_api_latency_metric_bucket{job=~"$job", instance=~"$instance", model=~"$model"}[$__rate_interval])
  )
)

histogram_quantile(
  0.50,
  sum by (model, le) (
    rate(litellm_llm_api_time_to_first_token_metric_bucket{job=~"$job", instance=~"$instance", model=~"$model"}[$__rate_interval])
  )
)

histogram_quantile(
  0.90,
  sum by (model, le) (
    rate(litellm_llm_api_time_to_first_token_metric_bucket{job=~"$job", instance=~"$instance", model=~"$model"}[$__rate_interval])
  )
)

histogram_quantile(
  0.95,
  sum by (model, le) (
    rate(litellm_llm_api_time_to_first_token_metric_bucket{job=~"$job", instance=~"$instance", model=~"$model"}[$__rate_interval])
  )
