histogram_quantile(
  0.99,
  sum by (model, le) (
    rate(litellm_llm_api_time_to_first_token_metric_bucket{job=~"$job", instance=~"$instance", model=~"$model"}[$__rate_interval])
  )
)

max by (litellm_model_name, api_provider, api_base_clean, model_id) (
  label_replace(
    litellm_deployment_state{job=~"$job", instance=~"$instance", litellm_model_name=~"$model", api_base!=""},
    "api_base_clean", "$1", "api_base", "([^?]+).*"
  )
)

sum by (litellm_model_name, api_base_clean, exception_class, exception_status) (
  label_replace(
    rate(litellm_deployment_failure_responses_total{job=~"$job", instance=~"$instance", api_base!="", litellm_model_name=~"$model"}[$__rate_interval]),
    "api_base_clean", "$1", "api_base", "([^?]+).*"
  )
)
